38	/// A sanitized failure suitable for returning from an MCP tool.
39	#[derive(Debug)]
40	pub enum Error {
41	    /// A tool argument is outside the broker's safe bounds.
42	    Parameter(String),
43	    /// An upstream failed or answered with an unexpected shape.
44	    Upstream(String),
45	}
46	
47	impl fmt::Display for Error {
48	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
49	        let (Self::Parameter(message) | Self::Upstream(message)) = self;
50	        f.write_str(message)
51	    }
52	}
53	
54	type Result<T = Value> = std::result::Result<T, Error>;
55	
56	fn parameter<T>(message: impl Into<String>) -> Result<T> {
57	    Err(Error::Parameter(message.into()))
58	}
59	
60	fn upstream<T>(message: impl Into<String>) -> Result<T> {
61	    Err(Error::Upstream(message.into()))
62	}
