90	/// Every per-service Arr naming difference as data: the resource path, lookup
91	/// term prefix, projected and upstream external-id keys, title field, and the
92	/// description of a valid external id.
93	struct ArrSpec {
94	    resource: &'static str,
95	    lookup_prefix: &'static str,
96	    external_key: &'static str,
97	    external_field: &'static str,
98	    title_field: &'static str,
99	    id_description: &'static str,
100	}
101	
102	const fn arr_spec(fields: [&'static str; 6]) -> ArrSpec {
103	    let [resource, lookup_prefix, external_key, external_field, title_field, id_description] =
104	        fields;
105	    ArrSpec { resource, lookup_prefix, external_key, external_field, title_field, id_description }
106	}
