128	    /// Catalog ids are decimal strings without leading zeros, capped to int32;
129	    /// Lidarr takes only the dashed canonical `MusicBrainz` UUID form (any case).
130	    fn id_valid(self, value: &str) -> bool {
131	        if self == Self::Lidarr {
132	            let hex = |group: &str| group.bytes().all(|byte| byte.is_ascii_hexdigit());
133	            return value.split('-').map(str::len).eq([8, 4, 4, 4, 12])
134	                && value.split('-').all(hex);
135	        }
136	        // `parse` alone would also accept a leading plus sign.
137	        let digits = value.bytes().all(|byte| byte.is_ascii_digit());
138	        digits && !value.starts_with('0') && value.parse::<i32>().is_ok()
139	    }
