198	/// A string no longer than the projected-string limit; anything else is dropped.
199	fn text(value: &Value) -> Option<&str> {
200	    let text = value.as_str()?;
201	    (text.chars().count() <= MAX_PROJECTED_STRING).then_some(text)
202	}
