204	/// An opaque identifier: an integer or a bounded string.
205	fn id(value: &Value) -> Value {
206	    let number = value.as_i64().map(Value::from);
207	    number.unwrap_or_else(|| json!(text(value)))
208	}
209	
210	/// Project a capped list of bounded strings, dropping invalid entries.
211	fn string_list(value: &Value) -> Option<Vec<&str>> {
212	    let entries = value.as_array()?.iter().take(MAX_LIST_ENTRIES);
213	    Some(entries.filter_map(text).collect())
214	}
