216	/// Project a capped season list to `season_number` and monitored flags.
217	fn season_summaries(value: &Value) -> Option<Vec<Value>> {
218	    let rows = value.as_array()?.iter().take(MAX_SEASON_ENTRIES);
219	    let summary = |row: &Value| {
220	        let number = row["seasonNumber"].as_i64()?;
221	        Some(json!({"season_number": number, "monitored": row["monitored"].as_bool()}))
222	    };
223	    Some(rows.filter_map(summary).collect())
224	}
