226	/// Add size and file-count fields from a row's embedded statistics block.
227	fn file_stats(mut item: Value, row: &Value, kind: &str) -> Value {
228	    let count = row["statistics"][format!("{kind}FileCount")].as_i64();
229	    item["size_on_disk_bytes"] = json!(row["statistics"]["sizeOnDisk"].as_i64());
230	    item[format!("{kind}_file_count")] = json!(count);
231	    item["has_file"] = json!(count.map(|count| count > 0));
232	    item
233	}
