235	/// Summarize one item (`id`, the service's title field) or album (`album_id`,
236	/// `title`); the requested id stands in when upstream omits the record's own.
237	fn summary(row: &Value, id_key: &str, title_field: &str, requested_id: u32) -> Value {
238	    let own_id = row["id"].as_i64().filter(|id| *id != 0);
239	    json!({
240	        (id_key): own_id.unwrap_or(requested_id.into()),
241	        "title": text(&row[title_field]),
242	        "monitored": row["monitored"].as_bool(),
243	    })
244	}
