285	fn sonarr_seasons(candidate: &Value, selection: Option<&[u32]>) -> Result<Vec<Value>> {
286	    let rows = candidate["seasons"].as_array().into_iter().flatten();
287	    let numbers: Vec<i64> = rows.filter_map(|row| row["seasonNumber"].as_i64()).collect();
288	    if numbers.is_empty() {
289	        return parameter("the lookup candidate has no season metadata");
290	    }
291	    let wanted = selection.map(|seasons| seasons.iter().map(|season| i64::from(*season)));
292	    let wanted: Option<Vec<i64>> = wanted.map(Iterator::collect);
293	    if wanted.iter().flatten().any(|season| !numbers.contains(season)) {
294	        return parameter("one or more seasons do not exist on the candidate");
295	    }
296	    let selected = |number: &i64| wanted.as_ref().is_none_or(|wanted| wanted.contains(number));
297	    let season = |number: &i64| json!({"seasonNumber": number, "monitored": selected(number)});
298	    Ok(numbers.iter().map(season).collect())
299	}
