301	/// The pagination block of a locally paginated result.
302	fn local_page(page: u32, page_size: u32, returned: usize, total: usize) -> Value {
303	    let start = (page as usize - 1) * page_size as usize;
304	    json!({
305	        "page": page,
306	        "page_size": page_size,
307	        "returned_count": returned,
308	        "total_count": total,
309	        "has_more": start + returned < total,
310	        "upstream_paginated": false,
311	        "upstream_truncated": false,
312	    })
313	}
