315	/// Bound an inclusive window of validated calendar dates to 31 days.
316	fn date_range(start: Date, end: Date) -> Result<()> {
317	    if (0..=30).contains(&(end - start).get_days()) {
318	        return Ok(());
319	    }
320	    parameter(DATE_RANGE)
321	}
