323	/// HTTP client for the allow-listed upstream APIs.
324	pub struct MediaClient {
325	    settings: Settings,
326	    http: reqwest::Client,
327	    /// The qBittorrent session id, held server-side and never projected.
328	    qbit_sid: Mutex<Option<String>>,
329	}
330	
331	impl MediaClient {
332	    /// # Panics
333	    /// When the TLS backend cannot be initialized.
334	    pub fn new(settings: Settings) -> Self {
335	        let builder = reqwest::Client::builder().redirect(Policy::none()).no_proxy();
336	        let http = builder.build().expect("the HTTP client initializes");
337	        Self { settings, http, qbit_sid: Mutex::new(None) }
338	    }
339	
340	    /// Address one upstream path; credentials travel in headers, never the URL.
341	    fn request(
342	        &self,
343	        service: impl Into<Service>,
344	        method: Method,
345	        path: &str,
346	    ) -> Result<RequestBuilder> {
347	        let service = service.into();
348	        let Some(upstream) = self.settings.upstream(service) else {
349	            return parameter(format!("{} is not configured on this broker", service.name()));
350	        };
351	        let url = format!("{}{}{path}", upstream.base_url, service.api_root());
352	        let request = self.http.request(method, url);
353	        Ok(match &upstream.auth {
354	            Auth::Key(key) => {
355	                let header = service.key_header().expect("key auth names a header");
356	                request.header(header, key.expose())
357	            }
358	            // Session auth attaches its cookie inside the qBittorrent exchange.
359	            Auth::Session { .. } => request,
360	        })
361	    }
362	
363	    /// Send one request under a total deadline, returning the status and a
364	    /// size-capped body without judging the status.
365	    async fn exchange(&self, request: RequestBuilder) -> Result<(u16, Vec<u8>)> {
366	        let limit = self.settings.max_response_bytes;
367	        let exchange = async {
368	            let Ok(mut response) = request.send().await else {
369	                return upstream(FAILED);
370	            };
371	            let status = response.status().as_u16();
372	            if response.content_length().unwrap_or(0) > limit as u64 {
373	                return upstream(OVERSIZED);
374	            }
375	            let mut body = Vec::new();
376	            while let Some(chunk) = response.chunk().await.or_else(|_| upstream(FAILED))? {
377	                body.extend_from_slice(&chunk);
378	                if body.len() > limit {
379	                    return upstream(OVERSIZED);
380	                }
381	            }
382	            Ok((status, body))
383	        };
384	        let deadline = tokio::time::timeout(self.settings.timeout, exchange);
385	        deadline.await.unwrap_or_else(|_| upstream("upstream request timed out"))
386	    }
387	
388	    /// One exchange that rejects any HTTP error status.
389	    async fn fetch(&self, request: RequestBuilder) -> Result<Vec<u8>> {
390	        let (status, body) = self.exchange(request).await?;
391	        if status >= 300 {
392	            return upstream(format!("upstream returned HTTP {status}"));
393	        }
394	        Ok(body)
395	    }
396	
397	    async fn json(&self, request: RequestBuilder) -> Result {
398	        let body = self.fetch(request).await?;
399	        serde_json::from_slice(&body).or_else(|_| upstream("upstream returned invalid JSON"))
400	    }
401	
402	    /// Fetch or write one upstream object.
403	    async fn record(&self, request: RequestBuilder) -> Result {
404	        let payload = self.json(request).await?;
405	        if !payload.is_object() {
406	            return upstream("upstream returned an unexpected response");
407	        }
408	        Ok(payload)
409	    }
410	
411	    /// Fetch a bounded list of upstream objects, dropping anything else.
412	    async fn rows(
413	        &self,
414	        service: impl Into<Service>,
415	        path: &str,
416	        query: &[(&str, String)],
417	    ) -> Result<Vec<Value>> {
418	        let request = self.request(service, Method::GET, path)?.query(query);
419	        match self.json(request).await? {
420	            Value::Array(rows) if rows.len() <= MAX_ITEMS => {
421	                Ok(rows.into_iter().filter(Value::is_object).collect())
422	            }
423	            _ => {
424	                let resource = path.split('/').nth(1).unwrap_or_default().to_lowercase();
425	                upstream(format!("upstream returned an unexpected {resource} response"))
426	            }
427	        }
428	    }
429	
430	    /// Send a broker-built JSON body, refusing unbounded payloads.
431	    async fn write(&self, service: ArrService, method: Method, path: &str, body: &Value) -> Result {
432	        let content = body.to_string();
433	        if content.len() > MAX_REQUEST_BYTES {
434	            return parameter("request payload exceeds the broker limit");
435	        }
436	        let request = self.request(service, method, path)?.body(content);
437	        self.record(request.header(CONTENT_TYPE, "application/json")).await
438	    }
