450	    /// Flip the monitored flag of the record at `path`; everything else
451	    /// round-trips untouched. Returns the updated upstream record.
452	    async fn set_monitored(&self, service: ArrService, path: &str, monitored: bool) -> Result {
453	        let mut record = self.record(self.request(service, Method::GET, path)?).await?;
454	        record["monitored"] = json!(monitored);
455	        self.write(service, Method::PUT, path, &record).await
456	    }
