458	    pub async fn inventory(
459	        &self,
460	        service: ArrService,
461	        page: u32,
462	        page_size: u32,
463	        search: Option<&str>,
464	    ) -> Result {
465	        let path = format!("/{}", service.spec().resource);
466	        let rows = self.rows(service, &path, &[]).await?;
467	        let mut items: Vec<Value> = rows.iter().map(|row| inventory_item(service, row)).collect();
468	        let query = search.unwrap_or_default().trim().to_lowercase();
469	        let title = |item: &Value| item["title"].as_str().unwrap_or_default().to_lowercase();
470	        items.retain(|item| title(item).contains(&query));
471	        let (total, size) = (items.len(), page_size as usize);
472	        let paged = items.into_iter().skip((page as usize - 1) * size).take(size);
473	        let items: Vec<Value> = paged.collect();
474	        let pagination = local_page(page, page_size, items.len(), total);
475	        Ok(json!({"service": service, "items": items, "pagination": pagination}))
476	    }
