507	    pub async fn search_candidates(&self, service: ArrService, query: &str, limit: u32) -> Result {
508	        let rows = self.lookup(service, query.to_owned()).await?;
509	        let shown = rows.iter().take(limit as usize);
510	        let items: Vec<Value> = shown.map(|row| lookup_item(row, service.spec())).collect();
511	        let truncated = rows.len() > limit as usize;
512	        Ok(json!({"service": service, "items": items, "upstream_truncated": truncated}))
513	    }
