515	    /// Add one exact catalog item; the broker builds the add body itself.
516	    pub async fn request_media(
517	        &self,
518	        service: ArrService,
519	        external_id: &str,
520	        quality_profile_id: u32,
521	        root_folder_path: &str,
522	        search_on_add: bool,
523	        seasons: Option<&[u32]>,
524	    ) -> Result {
525	        let spec = service.spec();
526	        if seasons.is_some() && service != ArrService::Sonarr {
527	            return parameter("seasons is only supported for sonarr");
528	        }
529	        let identifier = external_id.trim();
530	        if !service.id_valid(identifier) {
531	            let (expected, name) = (spec.id_description, Service::from(service).name());
532	            return parameter(format!("external_id must be {expected} for {name}"));
533	        }
534	        let rows = self.lookup(service, format!("{}{identifier}", spec.lookup_prefix)).await?;
535	        let matches = |row: &&Value| {
536	            let external = &row[spec.external_field];
537	            let number = external.as_i64().map(|id| id.to_string());
538	            let found = number.or_else(|| text(external).map(str::to_owned));
539	            found.is_some_and(|found| found.eq_ignore_ascii_case(identifier))
540	        };
541	        let Some(candidate) = rows.iter().find(matches) else {
542	            return parameter("no upstream candidate matches the external identifier");
543	        };
544	        if candidate["id"].as_i64().is_some_and(|id| id != 0) {
