702	    /// Two-phase delete of one item, or of one Lidarr album while leaving its
703	    /// artist in place: preview with a bound confirmation, then execute.
704	    pub async fn delete_media(
705	        &self,
706	        service: ArrService,
707	        item_id: u32,
708	        delete_files: bool,
709	        confirmation: Option<&str>,
710	        album_id: Option<u32>,
711	    ) -> Result {
712	        let mut query = vec![("deleteFiles", delete_files.to_string())];
713	        let (path, mut outcome) = match album_id {
714	            Some(_) if service != ArrService::Lidarr => {
715	                return parameter("album_id is only supported for lidarr");
716	            }
717	            Some(album_id) => {
718	                let path = format!("/album/{album_id}");
719	                let request = self.request(service, Method::GET, &path)?;
720	                let album = self.record(request).await?;
721	                if album["artistId"].as_i64() != Some(item_id.into()) {
722	                    return parameter("album_id does not belong to item_id");
723	                }
724	                let artist = self.item(service, item_id).await?;
725	                let artist = json!({"id": item_id, "title": text(&artist["artistName"])});
726	                let album = summary(&album, "album_id", "title", album_id);
727	                (path, json!({"item": album, "artist": artist}))
728	            }
729	            None => {
730	                let item = self.item(service, item_id).await?;
731	                query.push(("addImportListExclusion", "false".to_owned()));
732	                (service.item_path(item_id), json!({"item": service.item_summary(&item, item_id)}))
733	            }
734	        };
735	        outcome["service"] = json!(service);
736	        outcome["delete_files"] = json!(delete_files);
737	        let action = json!([DELETE_ACTION, service, item_id, album_id, delete_files]).to_string();
738	        let now = Timestamp::now().as_second();
739	        if let Some(token) = confirmation {
740	            self.confirmation_must_match(&action, token, now)?;
741	            let request = self.request(service, Method::DELETE, &path)?.query(&query);
742	            self.fetch(request).await?;
743	            outcome["deleted"] = json!(true);
744	        } else {
745	            let expires = now.saturating_add_unsigned(self.settings.confirmation_ttl.as_secs());
746	            let token = format!("{expires}.{}", self.signature(expires, &action));
747	            outcome["confirmation_required"] = json!(true);
748	            outcome["confirmation"] = json!(token);
749	            outcome["confirmation_expires_at"] = json!(expires);
750	        }
751	        Ok(outcome)
752	    }
753	
754	    /// Hex HMAC-SHA256, keyed by the bearer token, over an expiry and action.
755	    fn signature(&self, expires: i64, action: &str) -> String {
756	        let key = self.settings.bearer_token.expose().as_bytes();
757	        let mut mac = Hmac::<Sha256>::new_from_slice(key).expect("HMAC takes any key length");
758	        mac.update(format!("{expires}.{action}").as_bytes());
759	        let mut hex = String::new();
760	        for byte in mac.finalize().into_bytes() {
761	            let _ = write!(hex, "{byte:02x}");
762	        }
763	        hex
764	    }
765	
766	    /// Require a fresh token signed for exactly this action's parameters.
767	    fn confirmation_must_match(&self, action: &str, token: &str, now: i64) -> Result<()> {
768	        let (expires, signature) = token.split_once('.').unwrap_or_default();
769	        let expires = expires.parse().unwrap_or(i64::MIN);
770	        let expected = self.signature(expires, action);
771	        if !bool::from(signature.as_bytes().ct_eq(expected.as_bytes())) {
772	            return parameter("confirmation is not valid for this action");
773	        }
774	        if now >= expires {
775	            return parameter("confirmation has expired; request a fresh preview");
776	        }
777	        Ok(())
778	    }
