780	    pub async fn history(
781	        &self,
782	        media_type: MediaType,
783	        start: Date,
784	        end: Date,
785	        page: u32,
786	        page_size: u32,
787	        user_id: Option<u32>,
788	    ) -> Result {
789	        date_range(start, end)?;
790	        let offset = u64::from(page - 1) * u64::from(page_size);
791	        let request = self
792	            .request(Service::Tautulli, Method::GET, "")?
793	            .query(&[("cmd", "get_history")])
794	            .query(&[("start", offset), ("length", page_size.into())])
795	            .query(&[("media_type", media_type)])
796	            // Tautulli's inclusive date bounds are named after/before.
797	            .query(&[("after", start), ("before", end)])
798	            // Discrete playback events, not grouped or activity-expanded rows.
799	            .query(&[("grouping", 0), ("include_activity", 0)])
800	            .query(&[("user_id", user_id)]);
801	        let payload = self.json(request).await?;
802	        let response = &payload["response"];
803	        if response["result"] != "success" {
804	            return upstream("upstream history request was not successful");
805	        }
806	        let rows: Vec<&Value> = match response["data"]["data"].as_array() {
807	            Some(rows) if rows.len() <= page_size as usize => {
808	                rows.iter().filter(|row| row.is_object()).collect()
809	            }
810	            _ => return upstream("upstream returned an unexpected history response"),
811	        };
812	        // Re-apply the requested filters locally so a misbehaving upstream
813	        // can never return another household member's rows.
814	        let kind = json!(media_type);
815	        let users = user_id.map(|user| [json!(user), json!(user.to_string())]);
816	        let mut items = Vec::new();
817	        for row in &rows {
818	            let other_type = row.get("media_type").is_some_and(|found| *found != kind);
819	            let other_user = users.as_ref().is_some_and(|users| !users.contains(&row["user_id"]));
820	            if other_type || other_user {
821	                continue;
822	            }
823	            let status = row["watched_status"].as_f64();
824	            let known = status.filter(|status| WATCHED_STATUSES.contains(status));
825	            // The source-prefixed identifiers are approved for household matching.
826	            items.push(json!({
827	                "media_type": media_type,
828	                "tautulli_user_id": id(&row["user_id"]),
829	                "user_name": text(&row["friendly_name"]),
830	                "tautulli_rating_key": id(&row["rating_key"]),
831	                "tautulli_history_id": id(&row["id"]),
832	                "title": text(&row["title"]),
833	                "parent_title": text(&row["parent_title"]),
834	                "grandparent_title": text(&row["grandparent_title"]),
835	                "played_at": row["started"].as_number(),
836	                "duration_seconds": row["duration"].as_number(),
837	                "completed": known.map(|status| status >= 1.0),
838	            }));
839	        }
840	        let received = offset + rows.len() as u64;
841	        let full_page = rows.len() == page_size as usize;
842	        // An upstream total smaller than what was already received is never trusted.
843	        let total = response["data"]["recordsFiltered"].as_u64();
844	        let total = total.filter(|total| *total >= received);
845	        Ok(json!({
846	            "media_type": media_type,
847	            "start_date": start,
848	            "end_date": end,
849	            "user_id_filter": user_id,
850	            "pagination": {
851	                "page": page,
852	                "page_size": page_size,
853	                "returned_count": items.len(),
854	                "upstream_total_count": total,
855	                "has_more": total.map_or(full_page, |total| received < total),
856	                "upstream_paginated": true,
857	                "upstream_truncated": total.is_none() && full_page,
858	            },
859	            "items": items,
860	        }))
861	    }
