863	    /// Return projected Playback Reporting rows, fetched one day at a time.
864	    #[allow(clippy::too_many_arguments)] // mirrors the tool's argument list
865	    pub async fn jellyfin_history(
866	        &self,
867	        user_id: &str,
868	        media_type: MediaType,
869	        start: Date,
870	        end: Date,
871	        page: u32,
872	        page_size: u32,
873	        timezone_offset: f64,
874	    ) -> Result {
875	        date_range(start, end)?;
876	        let filter = match media_type {
877	            MediaType::Movie => "Movie",
878	            MediaType::Episode => "Episode",
879	            MediaType::Track => "Audio",
880	        };
881	        let query =
882	            [("filter", filter.to_owned()), ("timezoneOffset", timezone_offset.to_string())];
883	        let size = page_size as usize;
884	        let window = (page as usize - 1) * size..page as usize * size;
885	        let mut items = Vec::new();
886	        let mut total = 0;
887	        for day in start.series(1.day()).take_while(|day| *day <= end) {
888	            let path = format!("/user_usage_stats/{user_id}/{day}/GetItems");
889	            let request = self.request(Service::Jellyfin, Method::GET, &path)?.query(&query);
890	            let payload = self.json(request).await?;
891	            let rows = match payload.as_array() {
892	                Some(rows) if rows.iter().all(Value::is_object) => rows,
893	                _ => return upstream("upstream returned an unexpected Jellyfin history response"),
894	            };
895	            // Count every row for honest local pagination, but retain only the
896	            // requested page and project it before the day's payload is dropped.
897	            for row in rows {
898	                if window.contains(&total) {
899	                    // Combine the plugin's local time with its requested calendar date.
900	                    let played_at = text(&row["Time"]).map(|time| format!("{day}T{time}"));
901	                    let played_at = played_at.filter(|at| at.len() <= MAX_PROJECTED_STRING);
902	                    items.push(json!({
903	                        "jellyfin_user_id": user_id,
904	                        "media_type": media_type,
905	                        "played_at": played_at,
906	                        "jellyfin_item_id": id(&row["Id"]),
907	                        "jellyfin_history_id": id(&row["RowId"]),
908	                        "title": text(&row["Name"]),
909	                        "duration_seconds": row["Duration"].as_number(),
910	                    }));
911	                }
912	                total += 1;
913	                if total > MAX_ITEMS {
914	                    return upstream("upstream returned too many Jellyfin history rows");
915	                }
916	            }
917	        }
918	        Ok(json!({
919	            "jellyfin_user_id": user_id,
920	            "media_type": media_type,
921	            "start_date": start,
922	            "end_date": end,
923	            "timezone_offset": timezone_offset,
924	            "pagination": local_page(page, page_size, items.len(), total),
925	            "items": items,
926	        }))
927	    }
