938	    /// Log in to qBittorrent; the session id stays server-side only.
939	    ///
940	    /// The login answer carries the cookie in its headers, so it runs its own
941	    /// bounded exchange rather than [`MediaClient::fetch`].
942	    async fn qbit_login(&self) -> Result<String> {
943	        let Some(qbit) = self.settings.upstream(Service::Qbittorrent) else {
944	            return parameter("qbittorrent is not configured on this broker");
945	        };
946	        let Auth::Session { username, password } = &qbit.auth else {
947	            return parameter("qbittorrent is not configured on this broker");
948	        };
949	        let url = format!("{}{}/auth/login", qbit.base_url, Service::Qbittorrent.api_root());
950	        let form = [("username", username.as_str()), ("password", password.expose())];
951	        let body = url::form_urlencoded::Serializer::new(String::new()).extend_pairs(form).finish();
952	        if body.len() > MAX_REQUEST_BYTES {
953	            return parameter("qBittorrent credentials exceed the broker limit");
954	        }
955	        let request = self
956	            .http
957	            .request(Method::POST, url)
958	            .header(CONTENT_TYPE, "application/x-www-form-urlencoded")
959	            .body(body);
960	        let limit = self.settings.max_response_bytes;
961	        let attempt = async {
962	            let Ok(mut response) = request.send().await else {
963	                return upstream(FAILED);
964	            };
965	            let status = response.status().as_u16();
966	            let sid =
967	                response.headers().get_all(reqwest::header::SET_COOKIE).iter().find_map(|value| {
968	                    let value = value.to_str().ok()?;
969	                    let sid = value.strip_prefix("SID=")?.split(';').next()?;
970	                    valid_sid(sid).then(|| sid.to_owned())
971	                });
972	            if response.content_length().unwrap_or(0) > limit as u64 {
973	                return upstream(OVERSIZED);
974	            }
975	            let mut body = Vec::new();
976	            while let Some(chunk) = response.chunk().await.or_else(|_| upstream(FAILED))? {
977	                body.extend_from_slice(&chunk);
978	                if body.len() > limit {
979	                    return upstream(OVERSIZED);
980	                }
981	            }
982	            Ok((status, sid, body))
983	        };
984	        let deadline = tokio::time::timeout(self.settings.timeout, attempt);
985	        let (status, sid, body) =
986	            deadline.await.unwrap_or_else(|_| upstream("upstream request timed out"))?;
987	        let accepted = status < 300 && body.trim_ascii() == b"Ok.";
988	        let Some(sid) = sid.filter(|_| accepted) else {
989	            return upstream("upstream authentication failed");
990	        };
991	        *self.qbit_sid.lock().await = Some(sid.clone());
992	        Ok(sid)
993	    }
994	
995	    /// GET one qBittorrent path, re-authenticating exactly once on a 403.
996	    async fn qbit_fetch(&self, path: &str, query: &[(&str, String)]) -> Result<Vec<u8>> {
997	        for retried in [false, true] {
998	            let cached = self.qbit_sid.lock().await.clone();
999	            let sid = match cached {
1000	                Some(sid) => sid,
1001	                None => self.qbit_login().await?,
1002	            };
1003	            let request = self
1004	                .request(Service::Qbittorrent, Method::GET, path)?
1005	                .header(reqwest::header::COOKIE, format!("SID={sid}"))
1006	                .query(query);
1007	            let (status, body) = self.exchange(request).await?;
1008	            if status == 403 && !retried {
1009	                *self.qbit_sid.lock().await = None;
1010	                continue;
1011	            }
1012	            if status >= 300 {
1013	                return upstream(format!("upstream returned HTTP {status}"));
1014	            }
1015	            return Ok(body);
1016	        }
1017	        upstream(FAILED)
1018	    }
